20	/**
21	 * Runs a bootnode.
22	 */
23	export async function bootnodeHandler(args: BootnodeArgs & GlobalArgs): Promise<void> {
24	  const {discv5Args, metricsArgs, bootnodeDir, network, version, commit, peerId, enr, logger} =
25	    await bootnodeHandlerInit(args);
26	
27	  const abortController = new AbortController();
28	  const bindAddrs = discv5Args.bindAddrs;
29	
30	  logger.info("Lodestar Bootnode", {network, version, commit});
31	  logger.info("Bind address", bindAddrs);
32	  logger.info("Advertised address", {
33	    ip4: enr.getLocationMultiaddr("udp4")?.toString(),
34	    ip6: enr.getLocationMultiaddr("udp6")?.toString(),
35	  });
36	  logger.info("Identity", {peerId: peerId.toString(), nodeId: enr.nodeId});
37	  logger.info("ENR", {enr: enr.encodeTxt()});
38	
39	  // bootnode setup
40	  try {
41	    let metricsRegistry: RegistryMetricCreator | undefined;
42	    let metricsServer: HttpMetricsServer | undefined;
43	    if (metricsArgs.enabled) {
44	      metricsRegistry = new RegistryMetricCreator();
45	      metricsRegistry.static({
46	        name: "bootnode_version",
47	        help: "Bootnode version",
48	        value: {version, commit, network},
49	      });
50	      metricsServer = await getHttpMetricsServer(metricsArgs, {register: metricsRegistry, logger});
51	    }
52	
53	    const discv5 = Discv5.create({
54	      enr,
55	      peerId,
56	      bindAddrs: {
57	        ip4: (bindAddrs.ip4 ? multiaddr(bindAddrs.ip4) : undefined) as Multiaddr,
58	        ip6: bindAddrs.ip6 ? multiaddr(bindAddrs.ip6) : undefined,
59	      },
60	      config: {enrUpdate: !enr.ip && !enr.ip6},
61	      metricsRegistry: metricsRegistry as IDiscv5CreateOptions["metricsRegistry"],
62	    });
63	
64	    // If there are any bootnodes, add them to the routing table
65	    for (const bootEnrStr of Array.from(new Set(discv5Args.bootEnrs).values())) {
66	      const bootEnr = ENR.decodeTxt(bootEnrStr);
67	      logger.info("Adding bootnode", {
68	        ip4: bootEnr.getLocationMultiaddr("udp4")?.toString(),
69	        ip6: bootEnr.getLocationMultiaddr("udp6")?.toString(),
70	        peerId: (await bootEnr.peerId()).toString(),
71	        nodeId: enr.nodeId,
72	      });
73	      discv5.addEnr(bootEnr);
74	    }
75	
76	    // start the server
77	    await discv5.start();
78	
79	    // if there are peers in the local routing table, establish a session by running a query
80	    if (discv5.kadValues().length) {
81	      void discv5.findRandomNode();
82	    }
83	
84	    discv5.on("multiaddrUpdated", (addr) => {
85	      logger.info("Advertised socket address updated", {addr: addr.toString()});
86	    });
87	
88	    // respond with metrics every 10 seconds
89	    const printInterval = setInterval(() => {
90	      let ip4Only = 0;
91	      let ip6Only = 0;
92	      let ip4ip6 = 0;
93	      let unreachable = 0;
94	      for (const kadEnr of discv5.kadValues()) {
95	        const hasIp4 = kadEnr.getLocationMultiaddr("udp4");
96	        const hasIp6 = kadEnr.getLocationMultiaddr("udp6");
97	        if (hasIp4 && hasIp6) {
98	          ip4ip6++;
99	        } else if (hasIp4) {
100	          ip4Only++;
101	        } else if (hasIp6) {
102	          ip6Only++;
103	        } else {
104	          unreachable++;
105	        }
106	      }
107	      logger.info("Server metrics", {
108	        connectedPeers: discv5.connectedPeerCount,
109	        activeSessions: discv5.sessionService.sessionsSize(),
110	        ip4Nodes: ip4Only,
111	        ip6Nodes: ip6Only,
112	        ip4AndIp6Nodes: ip4ip6,
113	        unreachableNodes: unreachable,
114	      });
115	    }, 10_000);
116	
117	    // Intercept SIGINT signal, to perform final ops before exiting
118	    onGracefulShutdown(async () => {
119	      if (args.persistNetworkIdentity) {
120	        try {
121	          const enrPath = path.join(bootnodeDir, "enr");
122	          writeFile600Perm(enrPath, enr.encodeTxt());
123	        } catch (e) {
124	          logger.warn("Unable to persist enr", {}, e as Error);
125	        }
126	      }
127	      abortController.abort();
128	    }, logger.info.bind(logger));
129	
130	    abortController.signal.addEventListener(
131	      "abort",
132	      async () => {
133	        try {
134	          discv5.removeAllListeners();
135	          clearInterval(printInterval);
136	
137	          await metricsServer?.close();
138	          await discv5.stop();
139	          logger.debug("Bootnode closed");
140	        } catch (e) {
141	          logger.error("Error closing bootnode", {}, e as Error);
142	          // Must explicitly exit process due to potential active handles
143	          process.exit(1);
144	        }
145	      },
146	      {once: true}
147	    );
148	  } catch (e) {
149	    if (e instanceof ErrorAborted) {
150	      logger.info(e.message); // Let the user know the abort was received but don't print as error
151	    } else {
152	      throw e;
153	    }
154	  }
155	}
