157	/** Separate function to simplify unit testing of options merging */
158	// eslint-disable-next-line @typescript-eslint/explicit-function-return-type
159	export async function bootnodeHandlerInit(args: BootnodeArgs & GlobalArgs) {
160	  const {config, network} = getBeaconConfigFromArgs(args);
161	  const {version, commit} = getVersionData();
162	  const beaconPaths = getBeaconPaths(args, network);
163	  // Use a separate directory to store bootnode enr + peer-id
164	  const bootnodeDir = path.join(beaconPaths.dataDir, "bootnode");
165	  const {discv5: discv5Args} = parseNetworkArgs(args);
166	  const metricsArgs = parseMetricsArgs(args);
167	  if (!discv5Args) {
168	    // Unreachable because bootnode requires discv5 to be enabled - duh
169	    throw new Error("unreachable - bootnode requires discv5 to be enabled");
170	  }
171	
172	  // initialize directories
173	  mkdir(beaconPaths.dataDir);
174	  mkdir(bootnodeDir);
175	
176	  // Fetch extra bootnodes
177	  discv5Args.bootEnrs = (discv5Args.bootEnrs ?? []).concat(
178	    args.bootnodesFile ? readBootnodes(args.bootnodesFile) : [],
179	    isKnownNetworkName(network) ? await getNetworkBootnodes(network) : []
180	  );
181	
182	  const logger = initLogger(args, beaconPaths.dataDir, config, "bootnode.log");
183	  const {peerId, enr} = await initPeerIdAndEnr(args as unknown as BeaconArgs, bootnodeDir, logger, true);
184	
185	  return {discv5Args, metricsArgs, bootnodeDir, network, version, commit, peerId, enr, logger};
186	}
