47	export function isKnownNetworkName(network: string): network is NetworkName {
48	  return networkNames.includes(network as NetworkName);
49	}
50	
51	export type WeakSubjectivityFetchOptions = {
52	  weakSubjectivityServerUrl: string;
53	  weakSubjectivityCheckpoint?: string;
54	};
55	
56	// log to screen every 30s when downloading state from a lodestar node
57	const GET_STATE_LOG_INTERVAL = 30 * 1000;
58	
59	export function getNetworkData(network: NetworkName): {
60	  chainConfig: ChainConfig;
61	  depositContractDeployBlock: number;
62	  genesisFileUrl: string | null;
63	  bootnodesFileUrl: string | null;
64	  bootEnrs: string[];
65	} {
66	  switch (network) {
67	    case "mainnet":
68	      return mainnet;
69	    case "dev":
70	      return dev;
71	    case "gnosis":
72	      return gnosis;
73	    case "goerli":
74	      return goerli;
75	    case "ropsten":
76	      return ropsten;
77	    case "sepolia":
78	      return sepolia;
79	    case "holesky":
80	      return holesky;
81	    case "chiado":
82	      return chiado;
83	    case "ephemery":
84	      return ephemery;
85	    default:
86	      throw Error(`Network not supported: ${network}`);
87	  }
88	}
89	
90	export function getNetworkBeaconParams(network: NetworkName): ChainConfig {
91	  return getNetworkData(network).chainConfig;
92	}
93	
94	/**
95	 * Get genesisStateFile URL to download. Returns null if not available
96	 */
97	export function getGenesisFileUrl(network: NetworkName): string | null {
98	  return getNetworkData(network).genesisFileUrl;
99	}
100	
101	/**
102	 * Fetches the latest list of bootnodes for a network
103	 * Bootnodes file is expected to contain bootnode ENR's concatenated by newlines
104	 */
105	export async function fetchBootnodes(network: NetworkName): Promise<string[]> {
106	  const bootnodesFileUrl = getNetworkData(network).bootnodesFileUrl;
107	  if (bootnodesFileUrl === null) {
108	    return [];
109	  }
110	
111	  const bootnodesFile = await got.get(bootnodesFileUrl).text();
112	  return parseBootnodesFile(bootnodesFile);
113	}
114	
115	export async function getNetworkBootnodes(network: NetworkName): Promise<string[]> {
116	  const bootnodes = [...getNetworkData(network).bootEnrs];
117	
118	  // Hidden option for testing
119	  if (!process.env.SKIP_FETCH_NETWORK_BOOTNODES) {
120	    try {
121	      const bootEnrs = await fetchBootnodes(network);
122	      bootnodes.push(...bootEnrs);
123	    } catch (e) {
124	      // eslint-disable-next-line no-console
125	      console.error(`Error fetching latest bootnodes: ${(e as Error).stack}`);
126	    }
127	  }
128	
129	  return bootnodes;
130	}
131	
132	/**
133	 * Reads and parses a list of bootnodes for a network from a file.
134	 */
135	export function readBootnodes(bootnodesFilePath: string): string[] {
136	  const bootnodesFile = fs.readFileSync(bootnodesFilePath, "utf8");
137	
138	  const bootnodes = parseBootnodesFile(bootnodesFile);
139	  for (const enrStr of bootnodes) {
140	    try {
141	      ENR.decodeTxt(enrStr);
142	    } catch (e) {
143	      throw new Error(`Invalid ENR found in ${bootnodesFilePath}:\n    ${enrStr}`);
144	    }
145	  }
146	
147	  if (bootnodes.length === 0) {
148	    throw new Error(`No bootnodes found on file ${bootnodesFilePath}`);
149	  }
150	
151	  return bootnodes;
152	}
