200	export function getCheckpointFromArg(checkpointStr: string): Checkpoint {
201	  const checkpointRegex = new RegExp("^(?:0x)?([0-9a-f]{64}):([0-9]+)$");
202	  const match = checkpointRegex.exec(checkpointStr.toLowerCase());
203	  if (!match) {
204	    throw new Error(`Could not parse checkpoint string: ${checkpointStr}`);
205	  }
206	  return {root: fromHex(match[1]), epoch: parseInt(match[2])};
207	}
