209	export function getCheckpointFromState(state: BeaconStateAllForks): Checkpoint {
210	  return {
211	    // the correct checkpoint is based on state's slot, its latestBlockHeader's slot's epoch can be
212	    // behind the state
213	    epoch: computeCheckpointEpochAtStateSlot(state.slot),
214	    root: getLatestBlockRoot(state),
215	  };
