47	  // forkchoice errors
48	  const processShutdownCallback: ProcessShutdownCallback = (err) => {
49	    logger.error("Process shutdown requested", {}, err);
50	    process.kill(process.pid, "SIGINT");
51	  };
52	
53	  if (ACTIVE_PRESET === PresetName.minimal) logger.info("ACTIVE_PRESET == minimal preset");
54	
55	  // additional metrics registries
56	  const metricsRegistries: Registry[] = [];
57	  let networkRegistry: Registry | undefined;
58	  if (options.metrics.enabled) {
59	    networkRegistry = new Registry();
60	    metricsRegistries.push(networkRegistry);
61	  }
62	  const db = new BeaconDb(config, await LevelDbController.create(options.db, {metrics: null, logger}));
63	  logger.info("Connected to LevelDB database", {path: options.db.name});
64	
65	  // BeaconNode setup
66	  try {
67	    const {anchorState, wsCheckpoint} = await initBeaconState(
68	      options,
69	      args,
70	      config,
71	      db,
72	      logger,
73	      abortController.signal
74	    );
75	    const beaconConfig = createBeaconConfig(config, anchorState.genesisValidatorsRoot);
76	    const node = await BeaconNode.init({
77	      opts: options,
78	      config: beaconConfig,
79	      db,
80	      logger,
81	      processShutdownCallback,
82	      peerId,
83	      peerStoreDir: beaconPaths.peerStoreDir,
84	      anchorState,
85	      wsCheckpoint,
86	      metricsRegistries,
87	    });
88	
89	    // dev debug option to have access to the BN instance
90	    if (args.attachToGlobalThis) {
91	      (globalThis as unknown as {bn: BeaconNode}).bn = node;
92	    }
93	
94	    // Prune invalid SSZ objects every interval
95	    const {persistInvalidSszObjectsDir} = args;
96	    const pruneInvalidSSZObjectsInterval = persistInvalidSszObjectsDir
97	      ? setInterval(() => {
98	          try {
99	            pruneOldFilesInDir(
100	              persistInvalidSszObjectsDir,
101	              (args.persistInvalidSszObjectsRetentionHours ?? DEFAULT_RETENTION_SSZ_OBJECTS_HOURS) * HOURS_TO_MS
102	            );
103	          } catch (e) {
104	            logger.warn("Error pruning invalid SSZ objects", {persistInvalidSszObjectsDir}, e as Error);
105	          }
106	          // Run every ~1 hour
107	        }, HOURS_TO_MS)
108	      : null;
