116	          writeFile600Perm(enrPath, networkIdentity.enr);
117	        } catch (e) {
118	          logger.warn("Unable to persist enr", {}, e as Error);
119	        }
120	      }
121	      abortController.abort();
122	
123	      if (pruneInvalidSSZObjectsInterval !== null) {
124	        clearInterval(pruneInvalidSSZObjectsInterval);
125	      }
126	    }, logger.info.bind(logger));
127	
128	    abortController.signal.addEventListener(
129	      "abort",
130	      async () => {
131	        try {
132	          await node.close();
133	          logger.debug("Beacon node closed");
134	          // Explicitly exit until active handles issue is resolved
135	          // See https://github.com/ChainSafe/lodestar/issues/5642
136	          process.exit(0);
137	        } catch (e) {
138	          logger.error("Error closing beacon node", {}, e as Error);
139	          // Make sure db is always closed gracefully
140	          await db.close();
141	          // Must explicitly exit process due to potential active handles
142	          process.exit(1);
143	        }
144	      },
145	      {once: true}
146	    );
147	  } catch (e) {
148	    await db.close();
149	
150	    if (e instanceof ErrorAborted) {
151	      logger.info(e.message); // Let the user know the abort was received but don't print as error
152	    } else {
153	      throw e;
154	    }
155	  }
