158	/** Separate function to simplify unit testing of options merging */
159	// eslint-disable-next-line @typescript-eslint/explicit-function-return-type
160	export async function beaconHandlerInit(args: BeaconArgs & GlobalArgs) {
161	  const {config, network} = getBeaconConfigFromArgs(args);
162	
163	  const beaconNodeOptions = new BeaconNodeOptions(parseBeaconNodeArgs(args));
164	
165	  const {version, commit} = getVersionData();
166	  const beaconPaths = getBeaconPaths(args, network);
167	  // TODO: Rename db.name to db.path or db.location
168	  beaconNodeOptions.set({db: {name: beaconPaths.dbDir}});
169	  beaconNodeOptions.set({chain: {persistInvalidSszObjectsDir: beaconPaths.persistInvalidSszObjectsDir}});
170	  // Add metrics metadata to show versioning + network info in Prometheus + Grafana
171	  beaconNodeOptions.set({metrics: {metadata: {version, commit, network}}});
172	  beaconNodeOptions.set({metrics: {validatorMonitorLogs: args.validatorMonitorLogs}});
173	  // Add detailed version string for API node/version endpoint
174	  beaconNodeOptions.set({api: {version}});
175	
176	  // Combine bootnodes from different sources
177	  const bootnodes = (beaconNodeOptions.get().network?.discv5?.bootEnrs ?? []).concat(
178	    args.bootnodesFile ? readBootnodes(args.bootnodesFile) : [],
179	    isKnownNetworkName(network) ? await getNetworkBootnodes(network) : []
180	  );
181	  // Deduplicate and set combined bootnodes
182	  beaconNodeOptions.set({network: {discv5: {bootEnrs: [...new Set(bootnodes)]}}});
183	
184	  // Set known depositContractDeployBlock
185	  if (isKnownNetworkName(network)) {
186	    const {depositContractDeployBlock} = getNetworkData(network);
187	    beaconNodeOptions.set({eth1: {depositContractDeployBlock}});
188	  }
189	
190	  const logger = initLogger(args, beaconPaths.dataDir, config);
191	  const {peerId, enr} = await initPeerIdAndEnr(args, beaconPaths.beaconDir, logger);
192	  // Inject ENR to beacon options
193	  beaconNodeOptions.set({network: {discv5: {enr: enr.encodeTxt(), config: {enrUpdate: !enr.ip && !enr.ip6}}}});
